static const z_t60_t _zag1298[] = {{ .data = "/* collections.stringJoin -- borrow `parts` (read-only) and return a new\n   owned string. `parts` arrives by pointer, as a stack reftype parameter\n   does; the caller keeps it. */\nstatic z_@String@_t z_collections_stringJoin(\n    z_@List_String@_t* parts, z_@StringView@_t sep);\nstatic z_@String@_t z_collections_stringJoin(\n    z_@List_String@_t* parts, z_@StringView@_t sep) {\n    z_@String@_t out = {0};\n    uint64_t n = parts->length;\n    if (n == 0) {\n        out.capacity = 1;\n        out.data = (char*)z_xmalloc(1);\n        out.data[0] = '\\0';\n        return out;\n    }\n    uint64_t total = sep.size * (n - 1);\n    for (uint64_t i = 0; i < n; i++) {\n        total += parts->data[i].size;\n    }\n    out.size = total;\n    out.capacity = total + 1;\n    out.data = (char*)z_xmalloc(out.capacity + 1);\n    uint64_t pos = 0;\n    for (uint64_t i = 0; i < n; i++) {\n        if (i > 0 && sep.size > 0) {\n            memcpy(out.data + pos, sep.data, sep.size);\n            pos += sep.size;\n        }\n        memcpy(out.data + pos, parts->data[i].data, parts->data[i].size);\n        pos += parts->data[i].size;\n    }\n    out.data[total] = '\\0';\n    return out;\n}\n\n", .size = 1160 }};

